632→
633→export type FramePredicate =
634→  | { kind: 'slowFrames'; thresholdMs?: number }
635→  | { kind: 'markerSpike'; markerName: string; thread?: string; minSelfMs: number }
636→  | { kind: 'frameList'; frames: number[] };
637→
638→export interface CorrelateFrameSetsArgs {
639→  runId: string;
640→  setA: FramePredicate;
641→  setB: FramePredicate;
642→}
643→
644→export interface CorrelateFrameSetsResult {
645→  data: {
646→    sizeA: number;
647→    sizeB: number;
648→    intersection: number;
649→    union: number;
650→    jaccard: number;
651→    pctAinB: number;
652→    pctBinA: number;
653→    sampleOverlapFrames: number[];
654→  };
655→  provenance: Provenance;
656→}
657→
658→function resolvePredicate(
659→  db: Database.Database,
660→  runId: string,
661→  pred: FramePredicate
662→): Set<number> {
663→  if (pred.kind === 'frameList') {
664→    return new Set(pred.frames);
665→  }
666→
667→  if (pred.kind === 'slowFrames') {
668→    // Compute threshold = p95 of ms_frame if not provided
669→    const metas = db
670→      .prepare(
671→        'SELECT ms_frame FROM prism_frame_meta WHERE run_id = ? ORDER BY ms_frame'
672→      )
673→      .all(runId) as Array<{ ms_frame: number }>;
674→
675→    const threshold =
676→      pred.thresholdMs ??
677→      metas[Math.floor(metas.length * 0.95)]?.ms_frame ??
678→      0;
679→
680→    const slow = db
681→      .prepare(
682→        'SELECT frame_index FROM prism_frame_meta WHERE run_id = ? AND ms_frame > ?'
683→      )
684→      .all(runId, threshold) as Array<{ frame_index: number }>;
685→
686→    return new Set(slow.map(r => r.frame_index));
687→  }
688→
689→  // markerSpike
690→  let sql = `
691→    SELECT frame_index, SUM(self_ms) AS v
692→    FROM prism_frame_marker_samples
693→    WHERE run_id = ? AND marker_name = ?
694→  `;
695→  const params: unknown[] = [runId, pred.markerName];
696→  if (pred.thread) {
697→    sql += ' AND thread = ?';
698→    params.push(pred.thread);
699→  }
700→  sql += ' GROUP BY frame_index HAVING v > ?';
701→  params.push(pred.minSelfMs);
702→
703→  const rows = db.prepare(sql).all(...params) as Array<{
704→    frame_index: number;
705→    v: number;
706→  }>;
707→  return new Set(rows.map(r => r.frame_index));
708→}
709→
710→export function correlateFrameSets(
711→  db: Database.Database,
712→  args: CorrelateFrameSetsArgs
713→): CorrelateFrameSetsResult {
714→  const { runId, setA, setB } = args;
715→
716→  const frameSetA = resolvePredicate(db, runId, setA);
717→  const frameSetB = resolvePredicate(db, runId, setB);
718→
719→  const intersection: number[] = [];
