 1→/**
 2→ * db.ts — Prism SQLite helper
 3→ * Opens web/data/prism.sqlite (read-only by default).
 4→ * Resolves the path robustly relative to the repo root so it works
 5→ * whether the caller is run from web/ or from the repo root.
 6→ */
 7→
 8→import Database from 'better-sqlite3';
 9→import { fileURLToPath } from 'url';
10→import path from 'path';
11→
12→// __dirname equivalent for ESM
13→const __filename = fileURLToPath(import.meta.url);
14→const __dirname  = path.dirname(__filename);
15→
16→/**
17→ * Resolve the default prism.sqlite path.
18→ * Walk up from this file's directory until we find a "web/" parent,
19→ * then append data/prism.sqlite.
20→ */
21→export function resolveDbPath(override?: string): string {
22→  if (override) return path.resolve(override);
23→
24→  // This file lives at web/server/prism/db.ts
25→  // Go up 3 levels → repo root, then down into web/data/prism.sqlite
26→  const webDir = path.resolve(__dirname, '..', '..');
27→  return path.join(webDir, 'data', 'prism.sqlite');
28→}
29→
30→/**
31→ * Open the Prism database (read-only).
32→ * @param dbPath Optional override; defaults to web/data/prism.sqlite.
33→ */
34→export function openPrismDb(dbPath?: string): Database.Database {
35→  const resolved = resolveDbPath(dbPath);
36→  return new Database(resolved, { readonly: true });
37→}
